-- BABC MVP: durable school records and fictional demonstration accounts.
CREATE SCHEMA IF NOT EXISTS babc_school;
SET search_path TO babc_school, public;

CREATE TABLE students(id TEXT PRIMARY KEY,admission TEXT NOT NULL UNIQUE,name TEXT NOT NULL,class_name TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'Active',invite_hash TEXT,invite_expires TEXT);
CREATE TABLE accounts(id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,role TEXT NOT NULL CHECK(role IN ('principal','ict','bursar','academic_lead','teacher','student','parent')),student_id TEXT UNIQUE REFERENCES students(id),password_hash TEXT,status TEXT NOT NULL CHECK(status IN ('Pending','Active','Suspended')),demo INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS.US'));
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,expires_at TEXT NOT NULL);
CREATE TABLE student_login_defaults(account_id TEXT PRIMARY KEY REFERENCES accounts(id) ON DELETE CASCADE);
CREATE TABLE login_attempts(identifier TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE charges(id TEXT PRIMARY KEY,student_id TEXT NOT NULL REFERENCES students(id),description TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>0),reference TEXT NOT NULL,term TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS.US'),UNIQUE(student_id,reference));
CREATE TABLE payments(id TEXT PRIMARY KEY,student_id TEXT NOT NULL REFERENCES students(id),amount INTEGER NOT NULL CHECK(amount>0),reference TEXT NOT NULL UNIQUE,method TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('Pending','Verified','Rejected')),receipt TEXT UNIQUE,receipt_snapshot TEXT,created_at TEXT NOT NULL DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS.US'),verified_at TEXT);
CREATE TABLE salaries(id TEXT PRIMARY KEY,name TEXT NOT NULL,title TEXT NOT NULL,monthly_amount INTEGER NOT NULL CHECK(monthly_amount>0));
CREATE TABLE payables(id TEXT PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN ('Salary','Expense')),payee TEXT NOT NULL,staff_id TEXT REFERENCES salaries(id),period TEXT,description TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>0),reference TEXT NOT NULL UNIQUE,requested_by TEXT NOT NULL REFERENCES accounts(id),status TEXT NOT NULL DEFAULT 'Requested' CHECK(status IN ('Requested','Approved','Rejected','Paid')),approved_by TEXT REFERENCES accounts(id),paid_at TEXT,payment_reference TEXT UNIQUE,method TEXT,voucher TEXT UNIQUE,created_at TEXT NOT NULL DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS.US'));
CREATE TABLE funding(id TEXT PRIMARY KEY,amount INTEGER NOT NULL CHECK(amount>0),description TEXT NOT NULL,reference TEXT NOT NULL UNIQUE,created_at TEXT NOT NULL DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS.US'));
CREATE TABLE audit(id TEXT PRIMARY KEY,actor_id TEXT NOT NULL,actor_name TEXT NOT NULL,role TEXT NOT NULL,action TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS.US'));
CREATE TABLE assignments(id TEXT PRIMARY KEY,teacher_id TEXT NOT NULL REFERENCES accounts(id),subject TEXT NOT NULL,class_name TEXT NOT NULL,UNIQUE(subject,class_name));
CREATE TABLE class_teachers(class_name TEXT PRIMARY KEY,teacher_id TEXT NOT NULL REFERENCES accounts(id));
CREATE TABLE class_attendance(student_id TEXT NOT NULL REFERENCES students(id),school_date TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('Present','Absent','Late','Excused','Unmarked')),PRIMARY KEY(student_id,school_date));
CREATE TABLE scores(student_id TEXT NOT NULL REFERENCES students(id),assignment_id TEXT NOT NULL REFERENCES assignments(id),ca INTEGER NOT NULL CHECK(ca BETWEEN 0 AND 40),exam INTEGER NOT NULL CHECK(exam BETWEEN 0 AND 60),PRIMARY KEY(student_id,assignment_id));
CREATE TABLE attendance(student_id TEXT NOT NULL REFERENCES students(id),assignment_id TEXT NOT NULL REFERENCES assignments(id),school_date TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('Present','Absent','Late','Excused','Unmarked')),PRIMARY KEY(student_id,assignment_id,school_date));
CREATE TABLE reports(id TEXT PRIMARY KEY,student_id TEXT NOT NULL REFERENCES students(id),term TEXT NOT NULL,snapshot TEXT NOT NULL,published_at TEXT NOT NULL DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS.US'));
CREATE TABLE notices(id TEXT PRIMARY KEY,title TEXT NOT NULL,body TEXT NOT NULL,author TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS.US'));
CREATE TABLE school_settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE enrollments(student_id TEXT NOT NULL REFERENCES students(id),session TEXT NOT NULL,class_name TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'Active',PRIMARY KEY(student_id,session));
CREATE TABLE assessments(id TEXT PRIMARY KEY,session TEXT NOT NULL,term TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('Midterm','End of term')),class_name TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,status TEXT NOT NULL DEFAULT 'Draft' CHECK(status IN ('Draft','Checked','Approved','Published')),due_date TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES accounts(id),created_at TEXT NOT NULL DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS.US'),UNIQUE(session,term,kind,class_name,revision));
CREATE TABLE assessment_roster(assessment_id TEXT REFERENCES assessments(id),student_id TEXT REFERENCES students(id),name TEXT NOT NULL,admission TEXT NOT NULL,comment TEXT NOT NULL DEFAULT '',PRIMARY KEY(assessment_id,student_id));
CREATE TABLE assessment_subjects(id TEXT PRIMARY KEY,assessment_id TEXT NOT NULL REFERENCES assessments(id),subject TEXT NOT NULL,teacher_id TEXT NOT NULL REFERENCES accounts(id),status TEXT NOT NULL DEFAULT 'Draft' CHECK(status IN ('Draft','Submitted')),UNIQUE(assessment_id,subject));
CREATE TABLE assessment_scores(subject_id TEXT REFERENCES assessment_subjects(id),student_id TEXT REFERENCES students(id),ca INTEGER NOT NULL,exam INTEGER NOT NULL,PRIMARY KEY(subject_id,student_id));
CREATE TABLE academic_reports(id TEXT PRIMARY KEY,assessment_id TEXT REFERENCES assessments(id),student_id TEXT REFERENCES students(id),snapshot TEXT NOT NULL,published_at TEXT NOT NULL DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS.US'),UNIQUE(assessment_id,student_id));
CREATE TABLE guardian_links(account_id TEXT REFERENCES accounts(id),student_id TEXT REFERENCES students(id),PRIMARY KEY(account_id,student_id));
CREATE TABLE support_notes(id TEXT PRIMARY KEY,student_id TEXT REFERENCES students(id),author_id TEXT REFERENCES accounts(id),note TEXT NOT NULL,follow_up TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'Open' CHECK(status IN ('Open','Resolved')),created_at TEXT NOT NULL DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS.US'));
CREATE TABLE timetable(id TEXT PRIMARY KEY,session TEXT NOT NULL,class_name TEXT NOT NULL,subject TEXT NOT NULL,teacher_id TEXT NOT NULL REFERENCES accounts(id),weekday INTEGER NOT NULL CHECK(weekday BETWEEN 1 AND 5),starts TEXT NOT NULL,ends TEXT NOT NULL,room TEXT NOT NULL);
CREATE TABLE substitutions(id TEXT PRIMARY KEY,slot_id TEXT REFERENCES timetable(id),school_date TEXT NOT NULL,teacher_id TEXT NOT NULL REFERENCES accounts(id),UNIQUE(slot_id,school_date));
CREATE TABLE staff_meetings(id TEXT PRIMARY KEY,title TEXT NOT NULL,school_date TEXT NOT NULL,starts TEXT NOT NULL,link TEXT NOT NULL,minutes TEXT NOT NULL DEFAULT '',created_by TEXT REFERENCES accounts(id));
CREATE INDEX login_attempt_lookup ON login_attempts(identifier,created_at);
CREATE UNIQUE INDEX salary_period ON payables(staff_id,period) WHERE kind='Salary' AND status!='Rejected';

-- Only generated fictional data; no local school records or sessions are uploaded.
